SafeAddString(DE_SETTINGS_PANEL_DESC, "Verfolgt konfigurierte dynamische Begegnungen in den Zonen Steinfälle, Glenumbra und Auridon: aktueller Schritt, Teilnahme, Kistenzeitpunkt und ein geschätztes Respawn-Fenster. Encounter-Namen und Schritttexte stammen direkt aus ESO und werden in deiner Spielsprache angezeigt.", 1)
SafeAddString(DE_SETTINGS_SECTION_STATUS_CONTENT_DESC, "Legt fest, was im Statusfenster während eines verfolgten Encounters angezeigt wird, und in welchen Szenen das Fenster überhaupt erscheint.", 1)
SafeAddString(DE_SETTINGS_SECTION_STATUS_STYLE_DESC, "Größe, Farben und Hintergrund des Statusfensters. Diese Einstellungen ändern nicht, welche Informationen angezeigt werden.", 1)
SafeAddString(DE_SETTINGS_SECTION_CHEST_DESC, "Eine Meldung erscheint nur für Kistenzeitpunkte, für die beim aktuellen Encounter eine explizite und getestete Regel vorhanden ist. Der Kistenzeitpunkt wird nicht allgemein aus dem Schrittfortschritt abgeleitet.", 1)
SafeAddString(DE_SETTINGS_SECTION_RESET_DESC, "Das Zurücksetzen betrifft nur die Fensterposition und die Darstellung. Es ändert nicht, welche Informationen angezeigt werden, und wirkt sich nicht auf die Respawn-Timer-Overrides weiter unten aus.", 1)
SafeAddString(DE_SETTINGS_STATUS_SHOW, "Statusfenster anzeigen", 1)
SafeAddString(DE_SETTINGS_STATUS_MOVABLE, "Statusfenster verschiebbar", 1)
SafeAddString(DE_SETTINGS_STATUS_MOVABLE_TT, "Ermöglicht das Verschieben des Fensters und das Ändern seiner Breite. Im gesperrten Zustand reagiert das Statusfenster nicht auf die Maus.", 1)
SafeAddString(DE_SETTINGS_MINIMAL_MODE, "Minimode", 1)
SafeAddString(DE_SETTINGS_MINIMAL_MODE_TT, "Zeigt nur eine kompakte Statuszeile ohne Zone, Encounter-Namen und Abschnitt. Kann auch über den kleinen Schalter oben rechts im Statusfenster umgeschaltet werden.", 1)
SafeAddString(DE_SETTINGS_SHOW_CLOSE_BUTTON, "Schließen-Schaltfläche anzeigen", 1)
SafeAddString(DE_SETTINGS_SHOW_CLOSE_BUTTON_TT, "Zeigt die X-Schaltfläche oben rechts im Statusfenster zum Schließen. Bei ausgeblendeter Schaltfläche kann das Fenster weiterhin über „Statusfenster anzeigen“ ein- und ausgeblendet werden.", 1)
SafeAddString(DE_SETTINGS_SHOW_MINIMAL_TOGGLE_BUTTON, "Minimode-Schaltfläche anzeigen", 1)
SafeAddString(DE_SETTINGS_SHOW_MINIMAL_TOGGLE_BUTTON_TT, "Zeigt die kleine Schaltfläche oben rechts im Statusfenster zum Umschalten des Minimode. Bei ausgeblendeter Schaltfläche bleibt der Minimode weiterhin über die Einstellung „Minimode“ nutzbar.", 1)
SafeAddString(DE_SETTINGS_HIDE_MENUS, "In Menüs ausblenden", 1)
