SafeAddString(DE_SETTINGS_SHOW_STEP, "Schrittnummer im Status anzeigen", 1)
SafeAddString(DE_SETTINGS_SHOW_STEP_TT, "Ergänzt den Status während eines laufenden Encounters um „Schritt x/y“. Bei einer noch nicht eindeutig bestimmbaren Position erscheint „?/y“.", 1)
SafeAddString(DE_SETTINGS_SHOW_STEP_PROGRESS, "Schrittfortschritt im Status anzeigen", 1)
SafeAddString(DE_SETTINGS_SHOW_STEP_PROGRESS_TT, "Ergänzt den Status um den Prozentwert des aktuellen API-Ziels. Ist kein numerischer Wert verfügbar, erscheint ein Gedankenstrich.", 1)
SafeAddString(DE_SETTINGS_SHOW_PARTICIPATION, "Teilnahmestatus im Status anzeigen", 1)
SafeAddString(DE_SETTINGS_SHOW_PARTICIPATION_TT, "Ergänzt die Statuszeile um „Teilnahme erkannt“, „Teilnahme offen“ oder „Teilnahme unbekannt“. Eine erkannte Teilnahme bleibt für den aktuellen Encounter gespeichert.", 1)
